import math
def defined(t):
    try:
        math.sqrt(t - 2) / math.log(t - 2)
        return True
    except (ValueError, ZeroDivisionError):
        return False
pts = [1.5, 2, 2.0001, 2.5, 2.9999, 3, 3.0001, 4, 100]
print([t for t in pts if defined(t)])
opts = {'A': lambda t: 2 <= t < 3 or t > 3, 'B': lambda t: 2 < t < 3 or t > 3, 'C': lambda t: t > 2, 'D': lambda t: t > 3}
print([k for k, m in opts.items() if all(m(t) == defined(t) for t in pts)])
